# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İÇTİHAT, MÜÇTEHİT, MEZHEP VE TAKLİT KAVRAMLARI (FKH.10.2.2)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">İÇTİHAT SÜRECİ VE UNSURLARI</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• İçtihat: Delillerden fıkhi hüküm çıkarma çabası.</text>\n  <text x="32" y="108" font-size="10.8" fill="#1e3a8a">• Müçtehit (Fakih): İçtihat ehliyetine sahip âlim.</text>\n  <text x="32" y="128" font-size="10.8" fill="#1e3a8a">• İstinbat: Naslardan usul kurallarıyla hüküm üretme.</text>\n  <text x="32" y="148" font-size="10.8" fill="#1e3a8a">• Temel Kural: «Mevrid-i nasta içtihada مساغ yoktur»</text>\n  <text x="32" y="166" font-size="10.2" fill="#1e3a8a">  (Anlamı ve sübutu kesin nas bulunan konuda içtihat yapılmaz).</text>\n  <text x="32" y="188" font-size="10.8" fill="#1e3a8a">• Kolektif (Şûrâî) İçtihat: Fıkıh kurullarının ortak kararı.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">MEZHEP, TAKLİT, İTTİBA VE TELFİK</text>\n  <text x="372" y="88" font-size="10.8" fill="#14532d">• Mezhep: Müçtehit imamların sistemleşmiş fıkıh ekolü</text>\n  <text x="372" y="106" font-size="10.2" fill="#14532d">  (Hanefî, Şâfiî, Mâlikî, Hanbelî, Ca\'ferî).</text>\n  <text x="372" y="126" font-size="10.8" fill="#14532d">• Taklit: Delilini bilmeden bir müçtehidin görüşüne uymak.</text>\n  <text x="372" y="146" font-size="10.8" fill="#14532d">• İttiba: Hükmün delilini öğrenerek görüşü benimsemek.</text>\n  <text x="372" y="166" font-size="10.8" fill="#14532d">• Telfik: Tek bir meselede farklı mezhep hükümlerini</text>\n  <text x="372" y="184" font-size="10.2" fill="#14532d">  birleştirerek yeni bir uygulama oluşturmak.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Mezhepler dinin kendisi değil, dinin anlaşılma ve uygulanma biçimleridir; farklılıkları ümmet için rahmettir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MEKASIDÜ\'Ş-ŞERİA (ZARÛRİYYÂT-I HAMSE) VE FETVA-TAKVA</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">ZARÛRİYYÂT-I HAMSE (5 TEMEL GAYE)</text>\n  <text x="32" y="88" font-size="10.8" fill="#78350f">1. Hıfzü\'d-Dîn: Dinin ve inanç özgürlüğünün korunması</text>\n  <text x="32" y="110" font-size="10.8" fill="#78350f">2. Hıfzü\'n-Nefs: Canın ve beden sağlığının korunması</text>\n  <text x="32" y="132" font-size="10.8" fill="#78350f">3. Hıfzü\'l-Akl: Aklın ve iradenin korunması</text>\n  <text x="32" y="154" font-size="10.8" fill="#78350f">4. Hıfzü\'n-Nesl: Neslin, ailenin ve iffetin korunması</text>\n  <text x="32" y="176" font-size="10.8" fill="#78350f">5. Hıfzü\'l-Mâl: Malın ve helal kazancın korunması</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">FETVA, KAZA, RUHSAT VE AZİMET</text>\n  <text x="372" y="88" font-size="10.8" fill="#581c87">• Fetva: Müftünün sorulan fıkhi meseleye verdiği cevap</text>\n  <text x="372" y="106" font-size="10.2" fill="#581c87">  (bağlayıcı değildir, yol göstericidir).</text>\n  <text x="372" y="126" font-size="10.8" fill="#581c87">• Kaza: Hâkimin (kadının) verdiği bağlayıcı yargı kararı.</text>\n  <text x="372" y="146" font-size="10.8" fill="#581c87">• Azimet: Normal şartlarda geçerli olan asli hüküm.</text>\n  <text x="372" y="166" font-size="10.8" fill="#581c87">• Ruhsat: Zaruret, hastalık ve yolculuk gibi meşakkat</text>\n  <text x="372" y="184" font-size="10.2" fill="#581c87">  durumlarında tanınan kolaylaştırıcı hüküm.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Fıkhi hükümlerin temel gayesi kulların dünya ve ahiret yararını (maslahat) sağlamak ve kötülüğü (mefsedet) önlemektir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İBADETLER ÜNİTESİNE GİRİŞ: TAHARET VE NAMAZIN HİKMETİ (FKH.10.3.1)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">TAHARET (TEMİZLİK) ÇEŞİTLERİ</text>\n  <text x="32" y="88" font-size="10.8" font-weight="bold" fill="#064e3b">1. Necâsetten Taharet (Maddi Temizlik):</text>\n  <text x="42" y="106" font-size="10.5" fill="#064e3b">Beden, elbise ve namaz kılınacak yerin gözle</text>\n  <text x="42" y="122" font-size="10.5" fill="#064e3b">görülen pisliklerden (necâsetten) arındırılması.</text>\n  <text x="32" y="144" font-size="10.8" font-weight="bold" fill="#064e3b">2. Hadesten Taharet (Hükmî Temizlik):</text>\n  <text x="42" y="162" font-size="10.5" fill="#064e3b">Abdestsizlik (küçük hades) ve cünüplük (büyük hades)</text>\n  <text x="42" y="178" font-size="10.5" fill="#064e3b">durumunun abdest, gusül veya teyemmümle giderilmesi.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">NAMAZ İBADETİNİN ÖNEMİ VE HİKMETİ</text>\n  <text x="372" y="88" font-size="10.8" fill="#7c2d12">• İman-küfür arasındaki en belirgin amelî farktır.</text>\n  <text x="372" y="108" font-size="10.8" fill="#7c2d12">• Dinin direği ve müminin miracıdır.</text>\n  <text x="372" y="128" font-size="10.8" fill="#7c2d12">• İnsanı hayasızlıktan ve kötülükten (fahşâ ve</text>\n  <text x="372" y="146" font-size="10.8" fill="#7c2d12">  münkerden) alıkoyar (Ankebût, 29/45).</text>\n  <text x="372" y="166" font-size="10.8" fill="#7c2d12">• Zaman bilinci, temizlik alışkanlığı ve cemaatle</text>\n  <text x="372" y="184" font-size="10.8" fill="#7c2d12">  kılındığında toplumsal birlik ve eşitlik kazandırır.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">«Cennetin anahtarı namaz, namazın anahtarı ise temizliktir (abdesttir).» (Tirmizî, Tahâret, 1)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
